import{z as s,x as i,o as A,c as d,q as n,j as r,D as e,d as E,s as o,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"跨市场波动","description":"","frontmatter":{"title":"跨市场波动","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-crossmarket-vol.md","filePath":"quant/vt-crossmarket-vol.md","lastUpdated":1791063341000}'),p={name:"quant/vt-crossmarket-vol.md"};function u(m,a,h,D,c,f){const B=i("Mermaid");return A(),d("div",null,[a[2]||(a[2]=n('<h1 id="跨市场波动" tabindex="-1">跨市场波动 <a class="header-anchor" href="#跨市场波动" aria-label="Permalink to &quot;跨市场波动&quot;">​</a></h1><div class="epigraph"><p>波动在每个市场都说自己的方言：股指报曲面，外汇报三点，利率报正态；跨市场的第一件事不是比大小，而是把单位换成同一种方差。</p><footer>—— 据 Hamao, Masulis and Ng, 1990；Longin and Solnik, 2001 整理</footer></div><p><a href="/quant/vt-event-vol">上一课</a>把波动装进事件日程，对象仍是单一市场的名义。本课把语言搬到市场之间：股指、外汇、利率、商品、境内外两地。问题从「这个市场的方差贵不贵」变成「五个市场的方差预算怎么分、相关怎么定、币种怎么算」——方言不通，比较就是伪影。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个换算不过关，跨市场比较全是坐标错误。其一，报价方言：股指用执行价网格与 <a href="/quant/svi-ssvi">SVI/SSVI</a>；外汇用 <a href="/quant/fx-vol-quotes">ATM / RR / BF 三点</a>；利率用 <a href="/quant/sabr-calib">SABR</a> 的正态世界。同一个「偏斜」在 RR 里与在执行价斜率里不是同一个数。其二，币种：以美元计的欧元市场波动，混着汇率自己的方差，quanto 调整不是可选项。其三，相关：跨市场相关有体制性，<a href="/quant/correlation-breakdown">平静期估计</a>在压力日系统性失灵，拿它做预算等于用晴天测雨伞。</p><p><span class="marginnote">直觉类比：股指、外汇、利率的波动报价像三种方言——同一个「偏斜」在各市场连单位都不同。比较三地气温前要先统一成摄氏度，跨市场比波动前要先统一成同一口径的总方差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="统一口径的做法" tabindex="-1">统一口径的做法 <a class="header-anchor" href="#统一口径的做法" aria-label="Permalink to &quot;统一口径的做法&quot;">​</a></h3><p>先把各市场报价换算成同一种对象：按 delta 或 moneyness 归一的总方差，或直接用各市场方差互换的期限结构排成一张表。相关不用相关系数点估计表达，用可交易的工具：<a href="/quant/correlation-swap">相关互换</a>与分散篮子，让「相关」本身有价格。预算分配按「方差贡献 × 相关体制修正」算，修正规则预声明，不临时拟合。</p><p>传递结构有两条证据线可依：Hamao、Masulis 与 Ng 在 1990 年记录了美日英市场间隔夜的波动传递；Longin 与 Solnik 的长期结论是相关随体制走、牛市与熊市不同。共同的因子结构（<a href="/quant/vol-factor-model">波动率因子模型</a>）说明跨市场组合不必每市场独立建模：少数波动因子承担共同部分，特异部分走对角。境内外的摩擦是独立的基差：<a href="/quant/cn-index-basis-hedge-cost">A 股指数与境外对冲成本</a>、<a href="/quant/adr-premium">两地上市溢价</a>都是准入摩擦的价格，要当基差风险记账，不当免费套利。</p><p><span class="marginnote">术语翻译：quanto 调整就是把「用外币看的市场波动」折成「用本币记账的波动」时补上的一笔——汇率自己也在动，两个波动会交叉出第三项。不做这笔账，欧洲市场的美元波动里就混着欧元汇率的心跳。</span></p>',11)),(A(),r(l,null,{default:e(()=>[o(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E8%82%A1%E6%8C%87%EF%BC%9ASVI%20%E6%9B%B2%E9%9D%A2%22%5D%20--%3E%20UNI%5B%22%E7%BB%9F%E4%B8%80%E6%80%BB%E6%96%B9%E5%B7%AE%E8%A1%A8%22%5D%0A%20%20FX%5B%22%E5%A4%96%E6%B1%87%EF%BC%9AATM%20%2F%20RR%20%2F%20BF%22%5D%20--%3E%20UNI%0A%20%20IR%5B%22%E5%88%A9%E7%8E%87%EF%BC%9ASABR%20%E6%AD%A3%E6%80%81%22%5D%20--%3E%20UNI%0A%20%20CM%5B%22%E5%95%86%E5%93%81%EF%BC%9A%E5%AD%A3%E8%8A%82%E4%B8%8E%E5%AD%98%E5%82%A8%22%5D%20--%3E%20UNI%0A%20%20UNI%20--%3E%20COV%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%E4%B8%8E%E4%BD%93%E5%88%B6%E6%83%85%E6%99%AF%22%5D%0A%20%20Q%5B%22%E5%B8%81%E7%A7%8D%20quanto%20%E6%8A%98%E7%AE%97%22%5D%20--%3E%20COV%0A%20%20ACCESS%5B%22%E5%87%86%E5%85%A5%E4%B8%8E%E4%B8%A4%E5%9C%B0%E5%9F%BA%E5%B7%AE%22%5D%20--%3E%20BUD%5B%22%E8%B7%A8%E5%B8%82%E5%9C%BA%E6%B3%A2%E5%8A%A8%E9%A2%84%E7%AE%97%22%5D%0A%20%20COV%20--%3E%20BUD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("跨市场波动组合的真正对象是协方差矩阵的尾部：平静期相关低、压力日共同运动强。做情景必须先标准化波动再改相关——"),t("a",{href:"/quant/corr-break-scenario"},"相关性崩溃情景"),E("的规则——否则「相关性上升」被波动上升淹没，情景测了等于没测。溢价的跨市场比较同样要小心：VRP 的符号与大小按市场不同，股指上卖方收溢价，外汇视币对、商品视存储与季节而定——跨市场分散的前提是溢价不同源，同源的溢价分散不掉尾部。")],-1)),(A(),r(l,null,{default:e(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALM%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%3A%E4%BD%8E%E7%9B%B8%E5%85%B3%E3%80%81%E4%BD%8E%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20WRONG%5B%22%E9%94%99%E8%AF%AF%E8%B7%AF%E5%BE%84%3A%E5%8F%AA%E6%94%BE%E5%A4%A7%E6%B3%A2%E5%8A%A8%2C%E6%B2%BF%E7%94%A8%E5%B9%B3%E9%9D%99%E7%9B%B8%E5%85%B3%22%5D%0A%20%20CALM%20--%3E%20RIGHT%5B%22%E6%AD%A3%E7%A1%AE%E8%B7%AF%E5%BE%84%3A%E5%85%88%E6%A0%87%E5%87%86%E5%8C%96%E6%B3%A2%E5%8A%A8%2C%E5%86%8D%E4%B8%8A%E8%B0%83%E7%9B%B8%E5%85%B3%22%5D%0A%20%20WRONG%20--%3E%20MISS%5B%22%E5%8E%8B%E5%8A%9B%E6%97%A5%E7%BB%84%E5%90%88%E6%B3%A2%E5%8A%A8%E8%A2%AB%E4%BD%8E%E4%BC%B0%2C%E6%83%85%E6%99%AF%E7%99%BD%E6%B5%8B%22%5D%0A%20%20RIGHT%20--%3E%20SHOW%5B%22%E5%B0%BE%E9%83%A8%E5%85%B1%E5%90%8C%E8%BF%90%E5%8A%A8%E6%98%BE%E5%BD%A2%22%5D%0A%20%20MISS%20--%3E%20FIX%5B%22%E5%AF%B9%E7%85%A7%3A%E6%83%85%E6%99%AF%E6%98%AF%E5%90%A6%E7%9C%9F%E6%B5%8B%E5%88%B0%E4%BA%86%E5%8D%8F%E6%96%B9%E5%B7%AE%E5%B0%BE%E9%83%A8%22%5D%0A%20%20SHOW%20--%3E%20FIX%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">外汇市场的「25 delta RR」在股指的执行价网格里没有直接对应物；先统一成同一 delta 或同一 moneyness 的总方差再比较。这一步做错，后面找出的所有「跨市场相对价值」都是坐标伪影，交易越多错得越多。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写外汇期权定价与利率期限结构模型本身，只消费它们的报价口径；信用波动与通胀挂钩产品另课；准入额度、结算路径是制度问题，本课只把它们折成基差。跨市场的波动传递也不宣称因果：隔夜传递的证据是条件统计，把它读成因果关系是传导机制课的事。</p><p><span class="marginnote">常见误区：看见「美股跌、次日 A 股低开」就写「波动从美国传导到中国」。条件统计只说「通常伴随」，不说「导致」——公鸡打鸣与日出高度相关，但把打鸣当因果去建模，天阴的日子模型就废了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>方言先统一：各市场报价折成归一化总方差，再谈比较与预算。</li><li>相关用可交易工具表达（相关互换、分散篮子），不用点估计当预算。</li><li>情景先标准化波动再改相关；压力日共同运动是协方差矩阵的真正对象。</li><li>溢价按市场不同源：同源的溢价分散不掉尾部。</li><li>币种 quanto 与准入基差是独立风险，必须单独记账。</li><li>出处：Hamao, Masulis and Ng, 1990；Longin and Solnik, 2001；各市场报价口径见方言课。</li></ul>',6))])}const F=s(p,[["render",u]]);export{C as __pageData,F as default};
